using System.Diagnostics;
using System.Diagnostics.CodeAnalysis;
using System.Text.Json;
using MegaCrit.Sts2.Core.Models;

namespace CombatSolver.Engine.Common;

internal static class LazyMaskLayoutProbe
{
    private sealed class Counts
    {
        internal long Calls, Null, Length, TypeEqual, TypeRejected;
        internal long Equivalent, ZeroOnlyEquivalent, EquivalentElements, EquivalentLookups;
        internal long EquivalentDifferences, Elements, MaskLookups, Ticks;
    }
    private sealed class Cell { internal readonly Counts Local = new(), Shared = new(); }
    private static readonly ThreadLocal<Cell> Cells = new(()=>new(),trackAllValues:true);
    static LazyMaskLayoutProbe() => AppDomain.CurrentDomain.ProcessExit += (_,_)=>Write();

    internal static bool ObserveOriginalMatch([NotNullWhen(true)] MirroredHookListenerLayout? layout,
        IReadOnlyList<AbstractModel> source, Func<Type,MirroredHookMask> maskFor, bool local)
    {
        long start=Stopwatch.GetTimestamp();
        bool original=layout is not null && layout.Matches(source);
        Cell cell=Cells.Value!;Counts c=local?cell.Local:cell.Shared;c.Calls++;
        if(layout is null)c.Null++;
        else if(layout.Entries.Length!=source.Count)c.Length++;
        else if(original)c.TypeEqual++;
        else
        {
            c.TypeRejected++;c.Elements+=source.Count;
            int lookups=0,differences=0;bool equivalent=true,zeroOnly=true;
            for(int i=0;i<source.Count;i++)
            {
                Type type=source[i].GetType();
                if(type==layout.Entries[i].Type)continue;
                differences++;lookups++;
                MirroredHookMask current=maskFor(type);
                if(current!=layout.Entries[i].Mask){equivalent=false;break;}
                if(current!=0)zeroOnly=false;
            }
            c.MaskLookups+=lookups;
            if(equivalent)
            {
                c.Equivalent++;c.EquivalentElements+=source.Count;c.EquivalentLookups+=lookups;
                c.EquivalentDifferences+=differences;if(zeroOnly)c.ZeroOnlyEquivalent++;
            }
        }
        c.Ticks+=Stopwatch.GetTimestamp()-start;
        return original;
    }

    private static object Sum(IEnumerable<Counts> values)
    {
        Counts[] a=values.ToArray();
        return new
        {
            calls=a.Sum(x=>x.Calls),nullLayout=a.Sum(x=>x.Null),lengthRejected=a.Sum(x=>x.Length),
            typeEqual=a.Sum(x=>x.TypeEqual),typeRejected=a.Sum(x=>x.TypeRejected),
            maskEquivalent=a.Sum(x=>x.Equivalent),zeroOnlyEquivalent=a.Sum(x=>x.ZeroOnlyEquivalent),
            equivalentSourceElements=a.Sum(x=>x.EquivalentElements),equivalentMaskLookups=a.Sum(x=>x.EquivalentLookups),
            equivalentTypeDifferences=a.Sum(x=>x.EquivalentDifferences),typeRejectedSourceElements=a.Sum(x=>x.Elements),
            maskLookups=a.Sum(x=>x.MaskLookups),observerInclusiveElapsedSeconds=(double)a.Sum(x=>x.Ticks)/Stopwatch.Frequency,
        };
    }

    private static void Write()
    {
        string? path=Environment.GetEnvironmentVariable("LAZY_MASK_LAYOUT_PROBE_OUTPUT");
        if(string.IsNullOrWhiteSpace(path))return;
        File.WriteAllText(path,JsonSerializer.Serialize(new
        {
            scope="diagnostic only: return original type-matching decision, original lookup/rebuild/dispatch preserved; exactMask comparison performed only after a type rejection; no models or source lists retained; elapsed includes original match and observer, not CPU or performance acceptance",
            counterCells=Cells.Values.Count,local=Sum(Cells.Values.Select(x=>x.Local)),shared=Sum(Cells.Values.Select(x=>x.Shared)),
        },new JsonSerializerOptions{WriteIndented=true}));
    }
}

