using CombatSolver.Engine.Common;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;

namespace CombatSolver;

internal sealed partial class UnattendedTestRunner
{
    private void AssertLazyZeroMaskLayout(MirroredHookListenerFilter filter,AbstractModel[] models,AbstractModel external)
    {
        AbstractModel strike=ModelDb.Card<StrikeIronclad>(),defend=ModelDb.Card<DefendIronclad>();
        int checks=0;
        void Check(bool value,string message){if(!value)throw new InvalidOperationException(message);checks++;}
        Check(MirroredHookListenerFilter.MaskFor(strike.GetType())==0
            &&MirroredHookListenerFilter.MaskFor(defend.GetType())==0,"Zero-participation fixture is not neutral.");
        AbstractModel[] a=[strike,defend,external,external],b=[defend,strike,external,external];
        MirroredHookListenerLayout? layout=null;
        var first=(MirroredHookListenerSnapshot)filter.Filter(a,ref layout);
        MirroredHookListenerLayout original=layout!;
        var second=(MirroredHookListenerSnapshot)filter.Filter(b,ref layout);
        Check(ReferenceEquals(original,layout)&&ReferenceEquals(first.Layout,second.Layout),
            "Changed neutral types rebuilt the exact same dispatch layout.");
        Check(second.SequenceEqual(b,ReferenceEqualityComparer.Instance),"Neutral reuse changed receivers/order/duplicates.");
        Check(original.Entries[0].Type==strike.GetType()&&original.Entries[1].Type==defend.GetType(),
            "Shared immutable representative type metadata was modified.");
        Check(!original.Matches([defend,strike,external]),"Length mismatch was accepted.");
        AbstractModel active=models.First(m=>MirroredHookListenerFilter.MaskFor(m.GetType()) is not (0 or MirroredHookMask.All));
        Check(!original.Matches([active,strike,external,external]),"A newly active callback was treated as neutral.");
        AbstractModel otherExternal=models.First(m=>m.GetType().Assembly!=typeof(AbstractModel).Assembly
            &&m.GetType()!=external.GetType());
        Check(MirroredHookListenerFilter.MaskFor(otherExternal.GetType())==MirroredHookMask.All,
            "External fixture lost the existing unknown fallback.");
        Check(!original.Matches([defend,strike,otherExternal,external]),"Different unknown receiver type gained neutral reuse.");

        IGrouping<MirroredHookMask,AbstractModel> group=models.Where(m=>m.GetType().Assembly==typeof(AbstractModel).Assembly)
            .GroupBy(m=>MirroredHookListenerFilter.MaskFor(m.GetType()))
            .First(g=>g.Key is not (0 or MirroredHookMask.All)&&g.Select(m=>m.GetType()).Distinct().Count()>1);
        AbstractModel x=group.First(),y=group.First(m=>m.GetType()!=x.GetType());
        MirroredHookListenerLayout? nonzero=null;
        filter.Filter([x,external],ref nonzero);
        Check(!nonzero!.Matches([y,external]),"Different nonzero callback types bypassed the original type rule.");

        Parallel.For(0,64,index=>
        {
            MirroredHookListenerLayout? owned=original;
            AbstractModel[] current=index%2==0?a:b;
            var result=(MirroredHookListenerSnapshot)filter.Filter(current,ref owned);
            if(!ReferenceEquals(owned,original)||!result.SequenceEqual(current,ReferenceEqualityComparer.Instance))
                throw new InvalidOperationException("Concurrent neutral reuse changed layout or branch receivers.");
        });
        Check(original.Entries[0].Type==strike.GetType(),"Concurrent query modified original metadata.");
        _completedChecks.Add($"LazyZeroMaskLayout:Checks={checks}:DifferentZeroTypes:NonzeroUnknownLengthRefusal:ImmutableRepresentativeTypes:IdentityOrderDuplicates:Parallel64:ExistingFullStateForkRngContracts");
    }
}
